import click
from click.types import FuncParamType

def my_parser(value):
    if value != 'works':
        raise ValueError(f'input was {value=}, should be works')
    return value

param_type = FuncParamType(my_parser)

def test_func_param_type():
    try:
        param_type.convert('fails', None, None)
    except click.BadParameter as e:
        print(f"Caught expected error: {e}")
        # New behavior: self.fail(str(e), ...) -> BadParameter('input was fails=\'fails\', should be works', ...)
        assert str(e) == "input was fails='fails', should be works"
        print("New behavior verified.")

if __name__ == "__main__":
